class TemplateError(Exception):
    def __init__(self, message, line):
        super().__init__("line %d: %s" % (line, message))
        self.line = line


class _Undefined(object):
    __slots__ = ()

    def __repr__(self):
        return "UNDEFINED"


UNDEF = _Undefined()

KEYWORDS = {"and", "or", "not", "true", "false", "none", "in"}
FILTERS = {
    "upper": 0, "lower": 0, "trim": 0, "length": 0, "first": 0, "last": 0,
    "join": 1, "truncate": 1, "default": 1, "raw": 0,
}
BLOCK_NAMES = {"if", "elif", "else", "endif", "for", "endfor", "set"}
_DIGITS = "0123456789"
_NAME_START = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_"
_NAME_CHARS = _NAME_START + _DIGITS
_WS = " \t\n"


def _lex(s, line):
    toks = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c in " \t\n\r":
            i += 1
            continue
        if c in _DIGITS or (c == "-" and i + 1 < n and s[i + 1] in _DIGITS):
            j = i + 1
            while j < n and s[j] in _DIGITS:
                j += 1
            toks.append(("int", s[i:j]))
            i = j
            continue
        if c in _NAME_START:
            j = i + 1
            while j < n and s[j] in _NAME_CHARS:
                j += 1
            toks.append(("name", s[i:j]))
            i = j
            continue
        if c in "'\"":
            j = s.find(c, i + 1)
            if j == -1:
                raise TemplateError("unterminated string", line)
            toks.append(("str", s[i + 1:j]))
            i = j + 1
            continue
        if c == "=":
            if i + 1 < n and s[i + 1] == "=":
                toks.append(("op", "=="))
                i += 2
            else:
                toks.append(("op", "="))
                i += 1
            continue
        if c == "!":
            if i + 1 < n and s[i + 1] == "=":
                toks.append(("op", "!="))
                i += 2
                continue
            raise TemplateError("unexpected '!'", line)
        if c in "|(),.":
            toks.append(("op", c))
            i += 1
            continue
        raise TemplateError("unexpected character %r" % c, line)
    return toks


class _ExprParser(object):
    def __init__(self, toks, line, pos=0):
        self.toks = toks
        self.pos = pos
        self.line = line

    def err(self, msg):
        raise TemplateError(msg, self.line)

    def peek(self):
        if self.pos < len(self.toks):
            return self.toks[self.pos]
        return None

    def is_op(self, v):
        t = self.peek()
        return t is not None and t[0] == "op" and t[1] == v

    def is_kw(self, v):
        t = self.peek()
        return t is not None and t[0] == "name" and t[1] == v

    def next(self):
        t = self.peek()
        if t is None:
            self.err("unexpected end of expression")
        self.pos += 1
        return t

    def expect_op(self, v):
        if not self.is_op(v):
            self.err("expected %r" % v)
        self.pos += 1

    def at_end(self):
        return self.pos >= len(self.toks)

    def parse_full(self):
        e = self.parse_or()
        if not self.at_end():
            self.err("unexpected token %r" % (self.peek()[1],))
        return e

    def parse_or(self):
        left = self.parse_and()
        while self.is_kw("or"):
            self.pos += 1
            right = self.parse_and()
            left = ("or", left, right)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.is_kw("and"):
            self.pos += 1
            right = self.parse_not()
            left = ("and", left, right)
        return left

    def parse_not(self):
        if self.is_kw("not"):
            self.pos += 1
            return ("not", self.parse_not())
        return self.parse_cmp()

    def parse_cmp(self):
        left = self.parse_filter()
        if self.is_op("==") or self.is_op("!="):
            op = self.next()[1]
            right = self.parse_filter()
            if self.is_op("==") or self.is_op("!="):
                self.err("chained comparison")
            return ("eq" if op == "==" else "ne", left, right)
        return left

    def parse_filter(self):
        base = self.parse_primary()
        filters = []
        while self.is_op("|"):
            self.pos += 1
            t = self.next()
            if t[0] != "name":
                self.err("expected filter name")
            fname = t[1]
            if fname not in FILTERS:
                self.err("unknown filter %r" % fname)
            args = []
            if self.is_op("("):
                self.pos += 1
                if self.is_op(")"):
                    self.pos += 1
                else:
                    args.append(self.parse_or())
                    while self.is_op(","):
                        self.pos += 1
                        args.append(self.parse_or())
                    self.expect_op(")")
            if len(args) != FILTERS[fname]:
                self.err("wrong number of arguments for filter %r" % fname)
            filters.append((fname, args))
        if filters:
            has_raw = any(f[0] == "raw" for f in filters)
            return ("chain", base, filters, has_raw)
        return base

    def parse_primary(self):
        t = self.next()
        kind, val = t
        if kind == "int":
            return ("lit", int(val))
        if kind == "str":
            return ("lit", val)
        if kind == "name":
            if val == "true":
                return ("lit", True)
            if val == "false":
                return ("lit", False)
            if val == "none":
                return ("lit", None)
            if val in KEYWORDS:
                self.err("unexpected keyword %r" % val)
            segs = []
            while self.is_op("."):
                self.pos += 1
                s = self.next()
                if s[0] == "name":
                    if s[1] in KEYWORDS:
                        self.err("keyword in path")
                    segs.append(s[1])
                elif s[0] == "int" and not s[1].startswith("-"):
                    segs.append(s[1])
                else:
                    self.err("bad path segment")
            return ("path", val, segs)
        if kind == "op" and val == "(":
            e = self.parse_or()
            self.expect_op(")")
            return ("group", e)
        self.err("unexpected token %r" % (val,))


def _tokenize(t):
    toks = []
    i = 0
    n = len(t)
    closers = {"{": "}}", "%": "%}", "#": "#}"}
    while True:
        j = t.find("{", i)
        while j != -1 and not (j + 1 < n and t[j + 1] in "{%#"):
            j = t.find("{", j + 1)
        if j == -1:
            toks.append(["text", t[i:]])
            break
        toks.append(["text", t[i:j]])
        kind = t[j + 1]
        line = t.count("\n", 0, j) + 1
        q = t.find(closers[kind], j + 2)
        if q == -1:
            toks.append(["err", line])
            break
        content = t[j + 2:q]
        ls = content.startswith("-")
        if ls:
            content = content[1:]
        rs = content.endswith("-")
        if rs:
            content = content[:-1]
        toks.append(["tag", kind, content, line, ls, rs])
        i = q + 2
    for idx, tok in enumerate(toks):
        if tok[0] == "tag":
            if tok[4] and idx > 0 and toks[idx - 1][0] == "text":
                toks[idx - 1][1] = toks[idx - 1][1].rstrip(_WS)
            if tok[5] and idx + 1 < len(toks) and toks[idx + 1][0] == "text":
                toks[idx + 1][1] = toks[idx + 1][1].lstrip(_WS)
    return toks


def _parse(template):
    toks = _tokenize(template)
    root = []
    stack = []
    cur = root
    for tok in toks:
        if tok[0] == "text":
            if tok[1]:
                cur.append(("text", tok[1]))
            continue
        if tok[0] == "err":
            raise TemplateError("tag not closed", tok[1])
        _, kind, content, line, _ls, _rs = tok
        if kind == "#":
            continue
        ltoks = _lex(content, line)
        if kind == "{":
            p = _ExprParser(ltoks, line)
            e = p.parse_full()
            raw = e[0] == "chain" and e[3]
            cur.append(("out", e, raw))
            continue
        # block tag
        if not ltoks or ltoks[0][0] != "name" or ltoks[0][1] not in BLOCK_NAMES:
            raise TemplateError("unknown block tag", line)
        name = ltoks[0][1]
        if name == "if":
            e = _ExprParser(ltoks, line, 1).parse_full()
            body = []
            node = ["if", [[e, body]], None]
            cur.append(node)
            stack.append({"type": "if", "line": line, "node": node,
                          "in_else": False, "cur": body})
            cur = body
        elif name == "elif":
            if not stack or stack[-1]["type"] != "if" or stack[-1]["in_else"]:
                raise TemplateError("unexpected elif", line)
            e = _ExprParser(ltoks, line, 1).parse_full()
            body = []
            stack[-1]["node"][1].append([e, body])
            stack[-1]["cur"] = body
            cur = body
        elif name == "else":
            if len(ltoks) != 1:
                raise TemplateError("unexpected tokens after else", line)
            if not stack or stack[-1]["in_else"]:
                raise TemplateError("unexpected else", line)
            fr = stack[-1]
            body = []
            fr["in_else"] = True
            if fr["type"] == "if":
                fr["node"][2] = body
            else:
                fr["node"][4] = body
            fr["cur"] = body
            cur = body
        elif name == "endif" or name == "endfor":
            if len(ltoks) != 1:
                raise TemplateError("unexpected tokens after %s" % name, line)
            want = "if" if name == "endif" else "for"
            if not stack or stack[-1]["type"] != want:
                raise TemplateError("unexpected %s" % name, line)
            stack.pop()
            cur = stack[-1]["cur"] if stack else root
        elif name == "for":
            if (len(ltoks) < 3 or ltoks[1][0] != "name" or ltoks[1][1] in KEYWORDS
                    or ltoks[2] != ("name", "in")):
                raise TemplateError("malformed for", line)
            e = _ExprParser(ltoks, line, 3).parse_full()
            body = []
            node = ["for", ltoks[1][1], e, body, None]
            cur.append(node)
            stack.append({"type": "for", "line": line, "node": node,
                          "in_else": False, "cur": body})
            cur = body
        elif name == "set":
            if (len(ltoks) < 3 or ltoks[1][0] != "name" or ltoks[1][1] in KEYWORDS
                    or ltoks[2] != ("op", "=")):
                raise TemplateError("malformed set", line)
            e = _ExprParser(ltoks, line, 3).parse_full()
            cur.append(("set", ltoks[1][1], e))
    if stack:
        raise TemplateError("block not closed", stack[0]["line"])
    return root


def _truthy(v):
    if v is UNDEF or v is None:
        return False
    if isinstance(v, bool):
        return v
    if isinstance(v, int):
        return v != 0
    if isinstance(v, (str, list, dict)):
        return len(v) > 0
    return True


def _kind(v):
    if v is UNDEF or v is None:
        return "none"
    if isinstance(v, bool):
        return "bool"
    if isinstance(v, int):
        return "int"
    if isinstance(v, str):
        return "str"
    if isinstance(v, list):
        return "list"
    if isinstance(v, dict):
        return "dict"
    return "other"


def _eq(a, b):
    ka, kb = _kind(a), _kind(b)
    if ka != kb:
        return False
    if ka == "none":
        return True
    if ka == "list":
        return len(a) == len(b) and all(_eq(x, y) for x, y in zip(a, b))
    if ka == "dict":
        if set(a.keys()) != set(b.keys()):
            return False
        return all(_eq(a[k], b[k]) for k in a)
    try:
        return a == b
    except Exception:
        return False


def _render_value(v):
    if v is UNDEF or v is None:
        return ""
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, str):
        return v
    if isinstance(v, list):
        return ", ".join(_render_value(x) for x in v)
    if isinstance(v, dict):
        return "[object]"
    try:
        return str(v)
    except Exception:
        return ""


def _escape(s):
    return (s.replace("&", "&amp;").replace("<", "&lt;")
            .replace(">", "&gt;").replace('"', "&quot;"))


def _lookup(name, segs, tvars, ctx):
    if name in tvars:
        v = tvars[name]
    elif isinstance(ctx, dict) and name in ctx:
        v = ctx[name]
    else:
        return UNDEF
    for seg in segs:
        if isinstance(v, dict):
            v = v[seg] if seg in v else UNDEF
        elif isinstance(v, list):
            if seg[0] in _DIGITS:
                idx = int(seg)
                v = v[idx] if idx < len(v) else UNDEF
            else:
                v = UNDEF
        else:
            v = UNDEF
    return v


def _apply_filter(fname, v, args):
    if fname == "upper":
        return _render_value(v).upper()
    if fname == "lower":
        return _render_value(v).lower()
    if fname == "trim":
        return _render_value(v).strip()
    if fname == "length":
        if isinstance(v, (str, list, dict)):
            return len(v)
        return 0
    if fname == "first":
        return v[0] if isinstance(v, list) and v else UNDEF
    if fname == "last":
        return v[-1] if isinstance(v, list) and v else UNDEF
    if fname == "join":
        sep = _render_value(args[0])
        if isinstance(v, list):
            return sep.join(_render_value(x) for x in v)
        return _render_value(v)
    if fname == "truncate":
        s = _render_value(v)
        n = args[0]
        if not isinstance(n, int) or isinstance(n, bool):
            return s
        if len(s) <= n:
            return s
        return s[:max(n - 3, 0)] + "..."
    if fname == "default":
        if v is UNDEF or v is None:
            return args[0]
        return v
    if fname == "raw":
        return v
    return v


def _eval(node, tvars, ctx):
    t = node[0]
    if t == "lit":
        return node[1]
    if t == "path":
        return _lookup(node[1], node[2], tvars, ctx)
    if t == "group":
        return _eval(node[1], tvars, ctx)
    if t == "not":
        return not _truthy(_eval(node[1], tvars, ctx))
    if t == "and":
        a = _truthy(_eval(node[1], tvars, ctx))
        b = _truthy(_eval(node[2], tvars, ctx))
        return a and b
    if t == "or":
        a = _truthy(_eval(node[1], tvars, ctx))
        b = _truthy(_eval(node[2], tvars, ctx))
        return a or b
    if t == "eq":
        return _eq(_eval(node[1], tvars, ctx), _eval(node[2], tvars, ctx))
    if t == "ne":
        return not _eq(_eval(node[1], tvars, ctx), _eval(node[2], tvars, ctx))
    if t == "chain":
        v = _eval(node[1], tvars, ctx)
        for fname, args in node[2]:
            avals = [_eval(a, tvars, ctx) for a in args]
            v = _apply_filter(fname, v, avals)
        return v
    return UNDEF


def _run(nodes, tvars, ctx, out):
    for nd in nodes:
        t = nd[0]
        if t == "text":
            out.append(nd[1])
        elif t == "out":
            s = _render_value(_eval(nd[1], tvars, ctx))
            out.append(s if nd[2] else _escape(s))
        elif t == "if":
            done = False
            for cond, body in nd[1]:
                if _truthy(_eval(cond, tvars, ctx)):
                    _run(body, tvars, ctx, out)
                    done = True
                    break
            if not done and nd[2] is not None:
                _run(nd[2], tvars, ctx, out)
        elif t == "for":
            _, name, expr, body, else_body = nd
            v = _eval(expr, tvars, ctx)
            if isinstance(v, list):
                items = list(v)
            elif isinstance(v, dict):
                items = list(v.keys())
            else:
                items = []
            saved = dict(tvars)
            if items:
                n = len(items)
                for i, it in enumerate(items):
                    tvars[name] = it
                    tvars["loop"] = {
                        "index": i + 1,
                        "index0": i,
                        "first": i == 0,
                        "last": i == n - 1,
                        "length": n,
                    }
                    _run(body, tvars, ctx, out)
            elif else_body is not None:
                _run(else_body, tvars, ctx, out)
            tvars.clear()
            tvars.update(saved)
        elif t == "set":
            tvars[nd[1]] = _eval(nd[2], tvars, ctx)


def render(template: str, ctx: dict) -> str:
    nodes = _parse(template)
    if ctx is None:
        ctx = {}
    out = []
    _run(nodes, {}, ctx, out)
    return "".join(out)
